import itertools

def get_next_state(state, k):
    n = len(state)
    k_idx = k - 1
    target_coin = state[k_idx]

    start = k_idx
    while start > 0 and state[start-1] == target_coin:
        start -= 1

    end = k_idx
    while end < n - 1 and state[end+1] == target_coin:
        end += 1

    run = state[start : end+1]
    remaining = state[:start] + state[end+1:]
    return run + remaining

def is_goal(state):
    n_a = state.count('A')
    n_c = state.count('C')
    a_adj_c = 0
    for i in range(len(state)):
        if state[i] == 'A':
            is_adj_to_c = False
            if i > 0 and state[i-1] == 'C':
                is_adj_to_c = True
            if i < len(state) - 1 and state[i+1] == 'C':
                is_adj_to_c = True
            if is_adj_to_c:
                a_adj_c += 1
    return a_adj_c <= 1

def solve_for_m(m):
    n = 2 * m
    # Generate all unique configurations of m A's and m C's
    configs = []
    for indices in itertools.combinations(range(n), m):
        config = ['C'] * n
        for idx in indices:
            config[idx] = 'A'
        configs.append(tuple(config))

    results = []
    for k in range(1, n + 1):
        all_work = True
        for config in configs:
            curr = config
            visited = set()
            while not is_goal(curr):
                if curr in visited:
                    all_work = False
                    break
                visited.add(curr)
                curr = get_next_state(curr, k)
            if not all_work:
                break
        results.append(all_work)
    return results

for m in range(1, 9):
    res = solve_for_m(m)
    # Find a and b
    a = -1
    b = -1
    for k in range(1, 2*m+1):
        if res[k-1]:
            if a == -1:
                a = k
            b = k
    print(f"m={m}, a={a}, b={b}")
